/* ---------- motor de produtividade ----------
   produtividade = unidades por pessoa por hora, derivada da linha de base
   do tipo de operação. A meta de uma operação passa a ser:
       meta = volume / (pessoas x produtividade)
   Com isso 800 pneus com 2 pessoas deixa de ter a mesma meta que
   1.500 pneus com 4 pessoas — que é o que acontecia com meta fixa. */
function produtividadeBase(tipo) {
  if (!tipo) return null;
  const v = tipo.baseVolume, p = tipo.basePessoas, h = tipo.baseHoras;
  if (!v || !p || !h) return null;
  return v / (p * h);
}

/* minutos por unidade por pessoa — leitura mais intuitiva no dia a dia */
const minPorUnidade = (prod) => prod ? 60 / prod : null;

/* meta em horas para uma operação concreta */
function metaDaOperacao(op, tipo, params) {
  const fixa = tipo ? tipo.metaHoras : 0;
  if (!params.metaDinamica) return { horas: fixa, dinamica: false, motivo: "meta fixa do tipo" };
  const prod = produtividadeBase(tipo);
  const pessoas = pessoasDaOperacao(op, tipo);
  const vol = op.volume || 0;
  if (!prod || !pessoas || !vol) {
    return { horas: fixa, dinamica: false, motivo: "sem volume ou equipe informada — usando meta fixa" };
  }
  return { horas: vol / (pessoas * prod), dinamica: true, motivo: "calculada por volume e equipe", prod, pessoas, vol };
}

/* headcount que vai executar: terceirizados + pessoas da Superior.
   qtdPessoasSuperior é o campo novo; se não existir (registros antigos),
   cai para qtdSuperior, que na prática costumava coincidir. */
function pessoasDaOperacao(op, tipo) {
  const terc = op.qtdTerceirizada || 0;
  const sup = op.qtdPessoasSuperior != null ? op.qtdPessoasSuperior : (op.qtdSuperior || 0);
  const total = terc + sup;
  return total > 0 ? total : (tipo ? tipo.pessoas : 0);
}

/* ---------- helpers ---------- */
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const brl = (v) => "R$ " + (v || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const hhmm = (h) => {
  if (h == null) return "—";
  const m = Math.round(h * 60);
  return `${Math.floor(m / 60)}h${(m % 60).toString().padStart(2, "0")}`;
};
const fmtDT = (ts) => ts ? new Date(ts).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—";

function calcOp(op, params) {
  const tipo = params.tipos.find(t => t.id === op.tipoId) || params.tipos[0];
  const paletizado = tipo && tipo.modalidade === "paletizado";
  const pessoasRef = tipo ? tipo.pessoas : 0;
  const meta = metaDaOperacao(op, tipo, params);
  const metaHoras = meta.horas;
  /* Paletizado: não existe MdO terceirizada de referência, então não há
     custo, bônus nem economia a apurar — a operação só registra volume/SKU. */
  const referencia = paletizado ? 0 : pessoasRef * params.custoTerceirizada;
  const custoTerc = paletizado ? 0 : (op.qtdTerceirizada || 0) * params.custoTerceirizada;
  /* qtdSuperior = QUANTIDADE DE BÔNUS da operação (não headcount).
     Ex.: 2 bônus x R$200 = R$400 no bolo, rateado depois entre os nomeados. */
  const bonusPotencial = paletizado ? 0 : (op.qtdSuperior || 0) * params.bonusSuperior;
  let tempoReal = null, cumpriuMeta = null;
  if (op.status === "concluida" && op.inicio && op.fim) {
    tempoReal = (op.fim - op.inicio) / 3600000;
    cumpriuMeta = tempoReal <= metaHoras;
  }
  const bonusPago = cumpriuMeta === true ? bonusPotencial : 0;
  const custoReal = custoTerc + bonusPago;
  const economia = referencia - custoReal;
  /* rateio: divide o bônus pago igualmente entre os colaboradores nomeados */
  const nomeados = Array.isArray(op.colaboradores) ? op.colaboradores.filter(Boolean) : [];
  const valorPorPessoa = (bonusPago > 0 && nomeados.length > 0) ? bonusPago / nomeados.length : 0;
  /* produtividade realizada — base do aprendizado para recalibrar metas.
     Paletizado não tem headcount alocado, então não há produtividade a medir. */
  const pessoas = paletizado ? 0 : pessoasDaOperacao(op, tipo);
  const prodReal = (!paletizado && tempoReal && pessoas && op.volume) ? op.volume / (pessoas * tempoReal) : null;
  return { tipo, paletizado, pessoasRef, metaHoras, meta, referencia, custoTerc, bonusPotencial, bonusPago,
    custoReal, economia, tempoReal, cumpriuMeta, nomeados, valorPorPessoa, pessoas, prodReal,
    rateioPendente: bonusPago > 0 && nomeados.length === 0,
    totalPessoas: pessoas };
}

/* ---------- recalibração de metas ----------
   Compara a produtividade realizada com a linha de base de cada tipo e
   sugere um novo número quando há evidência suficiente. Nunca altera nada
   sozinho: apenas apresenta a sugestão para o gestor decidir. */
const MIN_AMOSTRA = 5;        // registros mínimos para sugerir algo
const TOLERANCIA_PCT = 10;    // abaixo disso a base é considerada boa

function analisarProdutividade(ops, params) {
  return params.tipos.map(tipo => {
    const base = produtividadeBase(tipo);
    const validas = ops
      .filter(o => o.tipoId === tipo.id && o.status === "concluida" && o.inicio && o.fim && o.volume > 0)
      .map(o => {
        const c = calcOp(o, params);
        return { op: o, c, prod: c.prodReal };
      })
      .filter(x => x.prod && isFinite(x.prod) && x.prod > 0);

    const n = validas.length;
    if (n === 0) {
      return { tipo, base, n: 0, suficiente: false, amostraMinima: MIN_AMOSTRA };
    }

    const prods = validas.map(x => x.prod).sort((a, b) => a - b);
    const media = prods.reduce((s, v) => s + v, 0) / n;
    const mediana = n % 2 ? prods[(n - 1) / 2] : (prods[n / 2 - 1] + prods[n / 2]) / 2;
    const desvio = Math.sqrt(prods.reduce((s, v) => s + (v - media) ** 2, 0) / n);
    const cv = media ? (desvio / media) * 100 : 0;   // coeficiente de variação
    const difPct = base ? ((mediana - base) / base) * 100 : null;

    /* mediana é mais robusta que média contra operações atípicas */
    const sugerida = mediana;
    const horasSugeridas = (tipo.baseVolume && tipo.basePessoas)
      ? tipo.baseVolume / (tipo.basePessoas * sugerida) : null;

    /* correlação entre variedade de SKU e desvio de tempo (Pearson).
       Só faz sentido se houver SKU informado em parte relevante da amostra. */
    const comSku = validas.filter(x => x.op.skus > 0);
    let corrSku = null;
    if (comSku.length >= MIN_AMOSTRA) {
      const xs = comSku.map(x => x.op.skus);
      const ys = comSku.map(x => x.prod);
      const mx = xs.reduce((s, v) => s + v, 0) / xs.length;
      const my = ys.reduce((s, v) => s + v, 0) / ys.length;
      const num = xs.reduce((s, v, i) => s + (v - mx) * (ys[i] - my), 0);
      const den = Math.sqrt(xs.reduce((s, v) => s + (v - mx) ** 2, 0) * ys.reduce((s, v) => s + (v - my) ** 2, 0));
      if (den) corrSku = num / den;
    }

    const suficiente = n >= MIN_AMOSTRA;
    const precisaAjuste = suficiente && difPct != null && Math.abs(difPct) > TOLERANCIA_PCT;

    return { tipo, base, n, validas, media, mediana, desvio, cv, difPct, sugerida, horasSugeridas,
      corrSku, nSku: comSku.length, suficiente, precisaAjuste, amostraMinima: MIN_AMOSTRA };
  });
}

/* dimensionamento: quantas pessoas para fechar dentro de um prazo alvo */
function pessoasNecessarias(tipo, volume, horasAlvo) {
  const prod = produtividadeBase(tipo);
  if (!prod || !volume || !horasAlvo) return null;
  return Math.ceil(volume / (prod * horasAlvo));
}

/* Avalia se a equipe alocada é suficiente.
   O alerta se baseia no EXCESSO DE TEMPO previsto, não no arredondamento
   do nº de pessoas: exigir 5 pessoas porque a conta deu 4,13 dispararia
   alarme por 3% de diferença e o painel perderia credibilidade. */
const TOLERANCIA_DIM = 15;   // % de excesso sobre o tempo de referência

function avaliarDimensionamento(tipo, volume, equipe) {
  const prod = produtividadeBase(tipo);
  const alvo = tipo ? (tipo.baseHoras || tipo.metaHoras) : 0;
  if (!prod || !volume || !equipe || !alvo) return null;
  const ideal = Math.ceil(volume / (prod * alvo));
  const previsto = volume / (equipe * prod);
  const excessoPct = ((previsto - alvo) / alvo) * 100;
  const critico = excessoPct > TOLERANCIA_DIM;
  return { prod, alvo, ideal, previsto, excessoPct, critico,
    faltam: Math.max(0, ideal - equipe),
    folga: equipe > ideal ? equipe - ideal : 0 };
}

/* ---------- janelas de tempo ---------- */
const H72 = 72 * 3600000;
const dentro72h = (ts) => ts != null && (Date.now() - ts) <= H72;
const mesDe = (ts) => { const d = new Date(ts); return d.getFullYear() * 12 + d.getMonth(); };
const mesAtual = () => mesDe(Date.now());
const inicioDoDia = (ts) => { const d = new Date(ts); d.setHours(0, 0, 0, 0); return d.getTime(); };
const ehHoje = (ts) => ts != null && inicioDoDia(ts) === inicioDoDia(Date.now());
const nomeMes = (idx) => new Date(Math.floor(idx / 12), idx % 12, 1)
  .toLocaleDateString("pt-BR", { month: "short", year: "2-digit" });

/* ---------- data planejada ----------
   dataPlanejada guarda o dia programado (timestamp do início do dia).
   Registros antigos não têm o campo — caem para a data de criação. */
const diaPlanejado = (op) => op.dataPlanejada != null ? op.dataPlanejada
  : (op.inicio ? inicioDoDia(op.inicio) : inicioDoDia(op.createdAt || Date.now()));
const ehDeHoje = (op) => diaPlanejado(op) === inicioDoDia(Date.now());
const diasAte = (ts) => Math.round((inicioDoDia(ts) - inicioDoDia(Date.now())) / 86400000);
const rotuloDia = (ts) => {
  const d = diasAte(ts);
  if (d === 0) return "Hoje";
  if (d === 1) return "Amanhã";
  if (d === -1) return "Ontem";
  return new Date(ts).toLocaleDateString("pt-BR", { weekday: "short", day: "2-digit", month: "2-digit" });
};
/* input date <-> timestamp, sem escorregar de fuso */
const dataParaInput = (ts) => {
  if (ts == null) return "";
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};
const inputParaData = (v) => {
  if (!v) return null;
  const [a, m, dd] = v.split("-").map(Number);
  return new Date(a, m - 1, dd, 0, 0, 0, 0).getTime();
};


/* agrega uma lista de {op,c} em totais */
function agregar(lista) {
  let referencia = 0, custoReal = 0, custoTerc = 0, bonusPago = 0, bonusPerdido = 0, economia = 0, noPrazo = 0;
  lista.forEach(({ c }) => {
    referencia += c.referencia; custoReal += c.custoReal; custoTerc += c.custoTerc;
    bonusPago += c.bonusPago; economia += c.economia;
    if (c.cumpriuMeta) noPrazo++; else bonusPerdido += c.bonusPotencial;
  });
  const n = lista.length;
  return { n, referencia, custoReal, custoTerc, bonusPago, bonusPerdido, economia, noPrazo,
    noPrazoPct: n ? (noPrazo / n) * 100 : 0, economiaPct: referencia ? (economia / referencia) * 100 : 0 };
}

/* variação percentual entre dois números (protege divisão por zero) */
function variacao(atual, anterior) {
  if (!anterior) return null;
  return ((atual - anterior) / Math.abs(anterior)) * 100;
}

/* ============================================================ */
export default function App() {
  const [modo, setModo] = useState(null); // null | "gestor" | "conferente"
  const [usuario, setUsuario] = useState(null); // nome do conferente logado
  const [ops, setOps] = useState([]);
  const [params, setParams] = useState(DEFAULT_PARAMS);
  const [loading, setLoading] = useState(true);
  const [now, setNow] = useState(Date.now());
  const [sync, setSync] = useState(false);
  /* fica true quando uma gravação não chegou ao banco — o aviso na tela
     evita que o conferente vá embora achando que registrou. */
  const [erroSalvar, setErroSalvar] = useState(false);

  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);

  const carregar = useCallback(async (silencioso) => {
    if (!silencioso) setSync(true);
    try {
      const p = await storage.get(K_PARAMS, SHARED);
      if (p?.value) {
        const parsed = JSON.parse(p.value);
        if (!Array.isArray(parsed.clientes)) parsed.clientes = DEFAULT_PARAMS.clientes;
        setParams(parsed);
      }
    } catch (e) {}
    try { const o = await storage.get(K_OPS, SHARED); if (o?.value) setOps(JSON.parse(o.value)); } catch (e) {}
    setSync(false); setLoading(false);
  }, []);

  useEffect(() => { carregar(true); }, [carregar]);

  /* auto-refresh a cada 20s — mantém gestor e conferente sincronizados */
  useEffect(() => {
    if (!modo) return;
    const t = setInterval(() => carregar(true), 20000);
    return () => clearInterval(t);
  }, [modo, carregar]);

  const persistOps = useCallback(async (next) => {
    setOps(next);
    try {
      await storage.set(K_OPS, JSON.stringify(next), SHARED);
      setErroSalvar(false);
    } catch (e) { console.error(e); setErroSalvar(true); }
  }, []);
  const persistParams = useCallback(async (next) => {
    setParams(next);
    try {
      await storage.set(K_PARAMS, JSON.stringify(next), SHARED);
      setErroSalvar(false);
    } catch (e) { console.error(e); setErroSalvar(true); }
  }, []);

  if (loading) return <Splash />;
  if (!modo) return <PortaEntrada params={params}
    onEntrar={(m, nome) => { setModo(m); setUsuario(nome || null); }} />;

  const sair = () => { setModo(null); setUsuario(null); };

  return <>
    <AvisoSemConexao visivel={erroSalvar} />
    {modo === "conferente"
    ? <AppConferente ops={ops} params={params} persistOps={persistOps} now={now} usuario={usuario}
        sair={sair} sync={sync} recarregar={() => carregar(false)} />
    : <AppGestor ops={ops} params={params} persistOps={persistOps} persistParams={persistParams}
        now={now} sair={sair} sync={sync} recarregar={() => carregar(false)} />}
  </>;
}

/* ============================================================
   AVISO DE FALHA DE GRAVAÇÃO
   Aparece fixo no topo quando um registro não chegou ao banco.
   Sem ele, o conferente sairia do CD achando que salvou.
   ============================================================ */
function AvisoSemConexao({ visivel }) {
  if (!visivel) return null;
  return (
    <div style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 9999,
      background: C.vermelho, color: "#fff", padding: "10px 14px",
      fontFamily: "Roboto, sans-serif", fontSize: 13, fontWeight: 500,
      display: "flex", alignItems: "center", gap: 8,
      boxShadow: "0 2px 8px rgba(0,0,0,.3)"
    }}>
      <AlertTriangle size={18} style={{ flexShrink: 0 }} />
      <span>
        <strong>Não foi possível salvar.</strong> Verifique a internet e
        toque em atualizar. Não feche o app até o aviso sumir.
      </span>
    </div>
  );
}

/* ============================================================
   PORTA DE ENTRADA — escolha do modo
   ============================================================ */
function PortaEntrada({ params, onEntrar }) {
  const [pedirPin, setPedirPin] = useState(null);   // null | "gestor" | "conferente"
  const [pin, setPin] = useState("");
  const [erro, setErro] = useState("");

  const conferentes = params.conferentes || [];
  /* Sem conferente cadastrado, o acesso segue livre — senão o app trava
     numa instalação nova, antes de o gestor conseguir cadastrar alguém. */
  const exigePin = conferentes.length > 0;

  const validar = () => {
    if (pedirPin === "gestor") {
      if (pin === (params.pinGestor || "1234")) return onEntrar("gestor", null);
      setErro("PIN incorreto."); setPin(""); return;
    }
    const achado = conferentes.find(c => c.pin === pin);
    if (achado) return onEntrar("conferente", achado.nome);
    setErro("PIN não encontrado. Confira com o gestor."); setPin("");
  };

  const entrarConferente = () => {
    if (!exigePin) return onEntrar("conferente", null);
    setPedirPin("conferente"); setPin(""); setErro("");
  };

  return (
    <div style={{ ...styles.page, minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <FontInject />
      <header style={styles.header}>
        <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
          <div style={styles.logoWrap}><img src={SBS_LOGO} alt="SBS Solution" style={{ height: 44 }} /></div>
          <div style={{ color: C.branco }}>
            <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 800, fontSize: 14 }}>MONITOR OPERACIONAL</div>
            <div style={{ fontFamily: "'Roboto',sans-serif", fontSize: 11, color: C.prata }}>Recebimento &amp; Expedição</div>
          </div>
        </div>
        <div style={{ ...styles.logoWrap, padding: "6px 10px" }}><img src={SUP_LOGO} alt="Superior Transportes" style={{ height: 28 }} /></div>
      </header>
      <div style={styles.accentBar} />

      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
        <div style={{ width: "100%", maxWidth: 460 }}>
          <h2 style={{ fontFamily: "'Montserrat',sans-serif", fontSize: 19, fontWeight: 800, color: C.navy, textAlign: "center", marginBottom: 6 }}>
            Como você vai acessar?
          </h2>
          <p style={{ textAlign: "center", color: C.prata, fontSize: 13, marginTop: 0, marginBottom: 24 }}>
            Selecione seu perfil de trabalho
          </p>

          {!pedirPin ? (
            <div style={{ display: "grid", gap: 14 }}>
              <button style={styles.portaBtn} onClick={entrarConferente}>
                <div style={{ ...styles.portaIcon, background: "#EAF6EE" }}><HardHat size={26} color={C.supVerde} strokeWidth={2.2} /></div>
                <div style={{ textAlign: "left" }}>
                  <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 800, fontSize: 16, color: C.navy }}>CONFERENTE</div>
                  <div style={{ fontSize: 12.5, color: C.prata, marginTop: 2 }}>
                    Registrar início e fim das operações{exigePin && <> <Lock size={11} style={{ verticalAlign: -1 }} /></>}
                  </div>
                </div>
              </button>
              <button style={styles.portaBtn} onClick={() => { setPedirPin("gestor"); setPin(""); setErro(""); }}>
                <div style={{ ...styles.portaIcon, background: "#EEF2F8" }}><Briefcase size={26} color={C.navy2} strokeWidth={2.2} /></div>
                <div style={{ textAlign: "left" }}>
                  <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 800, fontSize: 16, color: C.navy }}>
                    GESTOR <Lock size={13} style={{ verticalAlign: -1, marginLeft: 3 }} />
                  </div>
                  <div style={{ fontSize: 12.5, color: C.prata, marginTop: 2 }}>Cadastro, acompanhamento, custos e metas</div>
                </div>
              </button>
            </div>
          ) : (
            <div style={{ ...styles.card, textAlign: "center" }}>
              <Lock size={26} color={pedirPin === "gestor" ? C.navy2 : C.supVerde} />
              <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 700, color: C.navy, margin: "10px 0 14px", fontSize: 15 }}>
                {pedirPin === "gestor" ? "Acesso do Gestor" : "Acesso do Conferente"}
              </div>
              <input type="password" inputMode="numeric" value={pin} autoFocus
                onChange={e => { setPin(e.target.value); setErro(""); }}
                onKeyDown={e => e.key === "Enter" && validar()}
                placeholder="PIN"
                style={{ ...styles.input, textAlign: "center", fontSize: 22, letterSpacing: 8, fontFamily: "'Roboto Mono',monospace" }} />
              {erro && <div style={{ color: C.vermelho, fontSize: 12.5, marginTop: 8, fontWeight: 600 }}>{erro}</div>}
              <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
                <button style={{ ...styles.btnGhost, flex: 1, justifyContent: "center" }} onClick={() => { setPedirPin(null); setPin(""); setErro(""); }}>Voltar</button>
                <button style={{ ...styles.btnPrimary, flex: 1, justifyContent: "center" }} onClick={validar}>Entrar</button>
              </div>
              <div style={{ fontSize: 11, color: C.prata, marginTop: 12 }}>
                {pedirPin === "gestor"
                  ? "PIN inicial: 1234 — altere em Parâmetros"
                  : "Cada conferente tem seu PIN. Peça ao gestor se não souber o seu."}
              </div>
            </div>
          )}
        </div>
      </div>

      <footer style={styles.footer}>
        <div><strong style={{ display: "block", fontWeight: 600 }}>Pablo Bona · SBS Solution</strong>Lean Manufacturing &amp; Logística</div>
        <div style={{ color: C.prata, textAlign: "right" }}>Superior Transportes</div>
      </footer>
    </div>
  );
}

/* ============================================================
   APP DO CONFERENTE — tela única, mobile-first
   ============================================================ */
function AppConferente({ ops, params, persistOps, now, sair, sync, recarregar, usuario }) {
  const [obs, setObs] = useState({});
  const [aviso, setAviso] = useState("");

  /* Titularidade: quem iniciou é quem finaliza.
     Sem conferente identificado (nenhum cadastrado ainda), mantém aberto —
     senão o app trava numa instalação sem cadastro. */
  const podeFinalizar = (op) => {
    if (!op.conferenteInicio) return true;
    if (!usuario) return true;
    return op.conferenteInicio === usuario;
  };
  /* 0 = minha, em andamento · 1 = pendente · 2 = em andamento por outro */
  const prioridade = (op) => {
    if (op.status === "em_andamento") return podeFinalizar(op) ? 0 : 2;
    return 1;
  };

  /* O conferente só enxerga o que está programado para hoje.
     Operações em andamento continuam visíveis mesmo se viraram o dia,
     senão ele não conseguiria finalizar um turno que atravessou a meia-noite.
     Ordem: as que ele mesmo iniciou vêm primeiro, depois as pendentes,
     e por último as que estão com outro conferente. */
  const abertas = ops.filter(o => o.status !== "concluida" && o.status !== "cancelada")
    .filter(o => o.status === "em_andamento" || ehDeHoje(o))
    .sort((a, b) => prioridade(a) - prioridade(b));
  const futuras = ops.filter(o => o.status === "pendente" && diaPlanejado(o) > inicioDoDia(Date.now())).length;
  const finalizadasHoje = ops.filter(o => {
    if (o.status !== "concluida" || !o.fim) return false;
    const d = new Date(o.fim), h = new Date();
    return d.toDateString() === h.toDateString();
  });

  const iniciar = async (id) => {
    await persistOps(ops.map(o => o.id === id
      ? { ...o, status: "em_andamento", inicio: Date.now(), conferenteInicio: usuario || null } : o));
    setAviso("Operação iniciada — bom trabalho!"); setTimeout(() => setAviso(""), 3000);
  };
  const finalizar = async (id) => {
    /* Só quem iniciou fecha a operação. Guarda também no handler, e não só
       na interface: o botão pode não estar visível, mas a função existe. */
    const alvo = ops.find(o => o.id === id);
    if (alvo && !podeFinalizar(alvo)) {
      setAviso(`Somente ${alvo.conferenteInicio} pode finalizar esta operação.`);
      setTimeout(() => setAviso(""), 4000);
      return;
    }
    await persistOps(ops.map(o => o.id === id
      ? { ...o, status: "concluida", fim: Date.now(), conferenteFim: usuario || null,
          observacao: obs[id] ?? o.observacao ?? "" } : o));
    setAviso("Operação finalizada e registrada!"); setTimeout(() => setAviso(""), 3000);
  };


  return (
    <div style={styles.page}>
      <FontInject />
      <header style={{ ...styles.header, padding: "14px 18px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ ...styles.logoWrap, padding: "5px 7px" }}><img src={SBS_LOGO} alt="SBS" style={{ height: 34 }} /></div>
          <div style={{ color: C.branco }}>
            <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 800, fontSize: 13.5, display: "flex", alignItems: "center", gap: 6 }}>
              <HardHat size={16} /> CONFERENTE
            </div>
            <div style={{ fontFamily: "'Roboto',sans-serif", fontSize: 10.5, color: C.prata }}>
              {usuario ? usuario : "Registro de operações"}
            </div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button style={styles.headerBtn} onClick={recarregar} title="Atualizar">
            <RefreshCw size={16} style={{ animation: sync ? "spin 1s linear infinite" : "none" }} />
          </button>
          <button style={styles.headerBtn} onClick={sair} title="Sair"><LogOut size={16} /></button>
        </div>
      </header>
      <div style={styles.accentBar} />

      {aviso && <div style={styles.toast}><CheckCircle2 size={16} /> {aviso}</div>}

      <main style={{ padding: "18px 16px", maxWidth: 760, margin: "0 auto" }}>
        <SectionTitle icon={Activity}>Operações de hoje <Badge>{abertas.length}</Badge></SectionTitle>

        {abertas.length === 0 ? (
          <EmptyState text={futuras > 0
            ? `Nenhuma operação para hoje. Há ${futuras} programada${futuras > 1 ? "s" : ""} para os próximos dias.`
            : "Nenhuma operação programada para hoje. Aguarde o gestor cadastrar."} />
        ) : (
          <div style={{ display: "grid", gap: 14 }}>
            {abertas.map(op => {
              const c = calcOp(op, params);
              const rodando = op.status === "em_andamento";
              const elapsed = op.inicio ? (now - op.inicio) / 3600000 : 0;
              const over = rodando && elapsed > c.metaHoras;
              const meu = podeFinalizar(op);
              const deOutro = rodando && !meu;
              return (
                <div key={op.id} style={{ ...styles.card, padding: 16,
                  borderTop: `5px solid ${rodando ? (deOutro ? C.prata : over ? C.vermelho : C.laranja) : C.prataClaro}`,
                  ...(deOutro ? { background: C.bgLeve } : {}) }}>
                  {/* Cabeçalho da operação */}
                  <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
                    <TipoIcon tipo={c.tipo} big />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 800, fontSize: 18, color: C.navy, display: "flex", alignItems: "center", gap: 7, flexWrap: "wrap" }}>
                        {op.ref}
                        {op.demo && <span style={{ ...styles.pill, background: "#FFF3E0", color: C.laranjaEsc }}>exemplo</span>}
                      </div>
                      <div style={{ fontSize: 13, color: C.texto, marginTop: 2 }}>{op.cliente}</div>
                      {rodando && op.conferenteInicio && (
                        <div style={{ fontSize: 12, marginTop: 3, fontWeight: 600,
                          color: deOutro ? C.laranjaEsc : C.supVerde, display: "flex", alignItems: "center", gap: 4 }}>
                          <HardHat size={12} />
                          {deOutro ? op.conferenteInicio : "Você iniciou esta operação"}
                        </div>
                      )}
                    </div>
                    <DirTag dir={op.direcao} />
                  </div>

                  <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10, fontSize: 12, color: C.prata }}>
                    <span style={styles.infoChip}><Package size={12} /> {c.tipo?.label}</span>
                    {op.volume ? <span style={styles.infoChip}>{op.volume} un</span> : null}
                    <span style={styles.infoChip}><Users size={12} /> {op.qtdTerceirizada} terceirizados</span>
                    {op.qtdSuperior > 0 && <span style={styles.infoChip}><Award size={12} /> {op.qtdSuperior} bônus</span>}
                    <span style={styles.infoChip}><Target size={12} /> Meta {hhmm(c.metaHoras)}</span>
                  </div>

                  {/* Cronômetro grande */}
                  {rodando && (
                    <div style={{ textAlign: "center", padding: "16px 0 6px" }}>
                      <div style={{ fontSize: 10.5, fontWeight: 700, color: C.prata, textTransform: "uppercase", letterSpacing: 1 }}>Tempo decorrido</div>
                      <div style={{ fontFamily: "'Roboto Mono',monospace", fontSize: 44, fontWeight: 700, color: over ? C.vermelho : C.laranja, lineHeight: 1.1 }}>
                        {hhmm(elapsed)}
                      </div>
                      <div style={{ fontSize: 12, fontWeight: 600, color: over ? C.vermelho : C.verde }}>
                        {over ? "⚠ Meta ultrapassada" : `Dentro da meta (${hhmm(c.metaHoras)})`}
                      </div>
                      <div style={{ fontSize: 11, color: C.prata, marginTop: 4 }}>Início: {fmtDT(op.inicio)}</div>
                    </div>
                  )}

                  {/* Observação — só o titular edita; os demais leem */}
                  {rodando && deOutro && op.observacao && (
                    <div style={{ ...styles.obsBox, marginTop: 12 }}>
                      <MessageSquare size={11} /> {op.observacao}
                    </div>
                  )}
                  {rodando && meu && (
                    <div style={{ marginTop: 12 }}>
                      <label style={styles.fieldLabel}><MessageSquare size={11} style={{ verticalAlign: -1 }} /> Observação (ocorrência atípica)</label>
                      <textarea rows={2} style={{ ...styles.input, resize: "vertical", fontFamily: "'Roboto',sans-serif" }}
                        placeholder="Ex.: avaria em 3 pneus, atraso na chegada do veículo, falta de doca…"
                        value={obs[op.id] ?? op.observacao ?? ""}
                        onChange={e => setObs(d => ({ ...d, [op.id]: e.target.value }))} />
                    </div>
                  )}

                  {/* Botão de ação — grande. Quem não iniciou vê o estado, não o comando. */}
                  <div style={{ marginTop: 14 }}>
                    {!rodando ? (
                      <button style={{ ...styles.btnBig, background: C.verde }} onClick={() => iniciar(op.id)}>
                        <Play size={22} strokeWidth={2.6} /> INICIAR OPERAÇÃO
                      </button>
                    ) : meu ? (
                      <button style={{ ...styles.btnBig, background: C.navy }} onClick={() => finalizar(op.id)}>
                        <Square size={20} strokeWidth={2.6} /> FINALIZAR OPERAÇÃO
                      </button>
                    ) : (
                      <div style={{ ...styles.btnBig, background: C.bgLeve, color: C.prata,
                        border: `1px dashed ${C.prataClaro}`, cursor: "default", flexDirection: "column", gap: 3,
                        paddingTop: 12, paddingBottom: 12 }}>
                        <span style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 14 }}>
                          <Lock size={16} strokeWidth={2.4} /> EM ANDAMENTO POR {op.conferenteInicio.toUpperCase()}
                        </span>
                        <span style={{ fontSize: 11, fontWeight: 500, textTransform: "none", letterSpacing: 0 }}>
                          Só quem iniciou finaliza. Se houve troca de turno, o gestor ajusta.
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Finalizadas hoje */}
        {finalizadasHoje.length > 0 && (
          <>
            <SectionTitle icon={CheckCircle2}>Finalizadas hoje <Badge>{finalizadasHoje.length}</Badge></SectionTitle>
            <div style={{ display: "grid", gap: 8 }}>
              {finalizadasHoje.map(op => {
                const c = calcOp(op, params);
                return (
                  <div key={op.id} style={{ ...styles.opRow, opacity: .92 }}>
                    <TipoIcon tipo={c.tipo} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontFamily: "'Montserrat',sans-serif", fontWeight: 700, fontSize: 13.5, color: C.navy }}>{op.ref} · {op.cliente}</div>
                      <div style={{ fontSize: 11.5, color: C.prata, marginTop: 2 }}>
                        {hhmm(c.tempoReal)} · meta {hhmm(c.metaHoras)} · {fmtDT(op.fim)}
                      </div>
                    </div>
                    {c.cumpriuMeta
                      ? <span style={{ ...styles.pill, background: "#E8F5E9", color: C.verde }}><CheckCircle2 size={11} /> Na meta</span>
                      : <span style={{ ...styles.pill, background: "#FFEBEE", color: C.vermelho }}><AlertTriangle size={11} /> Fora</span>}
                  </div>
                );
              })}
            </div>
          </>
        )}
      </main>

      <footer style={styles.footer}>
        <div><strong style={{ display: "block", fontWeight: 600 }}>SBS Solution</strong>Monitor Operacional</div>
        <div style={{ color: C.prata, textAlign: "right" }}>Superior Transportes</div>
      </footer>
    </div>
  );
}

